record.field:
{
    "properties": {
        "partner_id": {
            "type": "number",
            "description": "ID of the partner (customer) for which the quotation is created"
        },
        "products":{
            "type": "string",
            "description": "JSON string of products for the quotation. Each product is a JSON object with the following properties: {id: product ID, quantity: product quantity}"
        }
    },
    "required": ["partner_id", "products"],
    "type": "object"
}

{
    "properties": {
        "order_id": {
            "type": "number",
            "description": "ID of the created quotation"
        },
        "message_id": {
            "type": "number",
            "description": "ID of the message from the customer"
        },
        "success": {
            "type": "boolean",
            "description": "Whether the quotation creation was successful"
        }
    },
    "required": ["order_id", "message_id", "success"],
    "type": "object"
}

{
    "properties": {
        "product_name": {
            "type": "string",
            "description": "Name of the product to search for"
        }
    },
    "required": ["product_name"],
    "type": "object"
}

{
    "properties": {
        "partner_name": {
            "type": "string",
            "description": "Name of the partner to search for"
        }
    },
    "required": ["partner_name"],
    "type": "object"
}
